// Concatenate migrations (+ seed) into supabase/setup.sql for pasting into the Supabase SQL Editor.
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = "supabase/migrations";
const files = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort().map((f) => join(dir, f));
files.push("supabase/seed.sql");
const out = [
  "-- ============================================================",
  "-- Sizzling Aroma — ALL-IN-ONE setup (generated by `npm run db:bundle`).",
  "-- Paste into Supabase → SQL Editor → Run. Safe to run again.",
  "-- ============================================================",
  "",
  ...files.map((f) => `-- >>> ${f}\n${readFileSync(f, "utf8")}\n`),
].join("\n");
writeFileSync("supabase/setup.sql", out);
console.log(`Wrote supabase/setup.sql from ${files.length} files.`);
